#!/usr/bin/env node
/**
 * weekly-synth-llm.mjs — optional local-LLM per-galaxy "week's theme" pass for
 * the weekly memory synthesis (`scripts/weekly-memory-synthesis.mjs`, U-GALAXY-MS1-B3).
 *
 * The weekly synthesis groups the trailing-7-day memos by galaxy and LISTS each
 * group's entries — it never says what the week MEANT for that domain. This adds
 * a 1-2 sentence theme per galaxy group, generated by the local Blackwell coder
 * model (qwen2.5-coder:32b) — $0 Claude tokens (a token SAVING: synthesis work
 * that would otherwise burn Claude is offloaded to the local LLM) and context
 * EXPANSION (a digest the `prism_memory:weekly_synthesis_get` consumer can lead
 * with). Default-OFF (PRISM_WEEKLY_LLM_SYNTH=1), fail-open: model down / "NONE" →
 * no theme line (byte-identical to the prior list-only output).
 *
 * Pure exports: buildGroupPrompt, cleanTheme. Async: synthesizeGroups.
 */

export const WEEKLY_LLM_MAX_GROUPS = Number(process.env.PRISM_WEEKLY_LLM_MAX_GROUPS) || 12;
export const WEEKLY_LLM_MIN_GROUP = Number(process.env.PRISM_WEEKLY_LLM_MIN_GROUP) || 3;
export const WEEKLY_LLM_MAX_WORDS = Number(process.env.PRISM_WEEKLY_LLM_MAX_WORDS) || 50;
// Titles fed per group — enough signal, bounded prompt.
const TITLES_PER_GROUP = Number(process.env.PRISM_WEEKLY_LLM_TITLES) || 12;

// entry → a short readable title (the memo's first `# ` heading, else its name).
function entryTitle(e) {
  const h = typeof e?.head === "string" && e.head ? e.head : null;
  return (h || e?.name || "").toString().replace(/\.md$/i, "").slice(0, 90);
}

/**
 * Pure: build the per-galaxy week's-theme prompt. `entries` is the galaxy group
 * (each { name, head? }). Caps the title list to keep the prompt bounded.
 */
export function buildGroupPrompt(galaxy, entries) {
  const titles = (Array.isArray(entries) ? entries : [])
    .slice(0, TITLES_PER_GROUP)
    .map((e) => `- ${entryTitle(e)}`)
    .join("\n");
  return [
    `These notes were added this week in the PRISM "${galaxy}" domain:`,
    titles,
    "",
    "In 1-2 sentences (max 40 words), summarize the WEEK'S THEME for this domain —",
    "what advanced, shifted, or recurred. Be substantive and specific; do NOT just",
    "restate the titles. If there is no coherent theme, reply exactly: NONE",
  ].join("\n");
}

/**
 * Pure: normalise a model reply into a vault-safe 1-2 sentence theme, or "" to
 * drop it. Drops empty / NONE / over-long; collapses whitespace; strips wrapping
 * quotes. Keeps internal punctuation (it's a short paragraph, not a list item).
 */
export function cleanTheme(text, maxWords = WEEKLY_LLM_MAX_WORDS) {
  if (typeof text !== "string") return "";
  let t = text.trim();
  if (!t) return "";
  t = t.replace(/\s+/g, " ").trim();             // collapse newlines/whitespace
  t = t.replace(/^["'`]+|["'`]+$/g, "").trim();   // strip wrapping quotes
  if (/^none\b/i.test(t) || t.toUpperCase() === "NONE") return "";
  if (t.split(/\s+/).length > maxWords) return ""; // rambled → drop
  return t;
}

/**
 * Synthesize a per-galaxy theme for the largest groups (>= minGroup entries, up
 * to maxGroups). `callFn(prompt) => Promise<string|null>` is injected. Returns a
 * Map<galaxy, theme>. Fail-open per group — any error/empty leaves no theme.
 */
export async function synthesizeGroups(groups, opts = {}) {
  const callFn = opts.callFn;
  const maxGroups = Number.isFinite(opts.maxGroups) ? opts.maxGroups : WEEKLY_LLM_MAX_GROUPS;
  const minGroup = Number.isFinite(opts.minGroup) ? opts.minGroup : WEEKLY_LLM_MIN_GROUP;
  const maxWords = Number.isFinite(opts.maxWords) ? opts.maxWords : WEEKLY_LLM_MAX_WORDS;
  const themes = new Map();
  if (typeof callFn !== "function" || !groups || typeof groups !== "object") return themes;
  // Largest groups first (most week-activity), gated by minGroup, capped at maxGroups.
  const ranked = Object.entries(groups)
    .filter(([, items]) => Array.isArray(items) && items.length >= minGroup)
    .sort((a, b) => b[1].length - a[1].length)
    .slice(0, Math.max(0, maxGroups));
  for (const [galaxy, items] of ranked) {
    try {
      const out = await callFn(buildGroupPrompt(galaxy, items));
      const theme = cleanTheme(out, maxWords);
      if (theme) themes.set(galaxy, theme);
    } catch { /* fail-open: no theme for this group */ }
  }
  return themes;
}
